/**
 * Per-member project mutes: a member's personal opt-out of one project's traffic.
 */
import { and, eq } from "drizzle-orm";
import { getDb, projectMutes } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId } from "./_mappers";
import type { OrgId, ProjectId, UserId } from "@/types/common";

/** Idempotent: muting an already-muted project leaves the existing row. */
export async function muteProject(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .insert(projectMutes)
    .values({
      orgId,
      userId,
      projectId,
      mutedAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing({
      target: [projectMutes.orgId, projectMutes.userId, projectMutes.projectId],
    })
    .run();
}

export async function unmuteProject(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .delete(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .run();
}

export async function listMutedProjectIds(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ProjectId[]> {
  const rows = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
      ),
    )
    .orderBy(projectMutes.mutedAt, projectMutes.projectId)
    .all();
  return rows.map((row) => brandId<ProjectId>(row.projectId));
}

export async function isProjectMuted(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<boolean> {
  const row = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .get();
  return row !== undefined;
}
EOF
